1|"use client";
2|
3|import { useCallback, useEffect, useRef, useState } from "react";
4|import { MSG_FAILED, MSG_RETRY } from "@/core/images";
5|import type { ImageResponse } from "@/core/images";
6|import { loadImageStyle } from "./image-style-prefs";
7|import { pickStartN } from "./picture-selection";
8|import type { ParaEntry } from "./picture-selection";
9|
10|export type PictureCard =
11|  | { phase: "idle" }
12|  | { phase: "loading" }
13|  | { phase: "ready"; url: string; caption: string; cached: boolean }
14|  | { phase: "error"; message: string };
15|
16|const POLL_MS = 3000;
17|const POLL_MAX = 40;
18|
19|function paraOf(node: Node | null): Element | null {
20|  if (!node) return null;
21|  const el = node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element);
22|  return el?.closest?.("p[id]") ?? null;
23|}
24|
25|async function postImage(body: unknown): Promise<ImageResponse> {
26|  const res = await fetch("/api/images", {
27|    method: "POST",
28|    headers: { "Content-Type": "application/json" },
29|    body: JSON.stringify(body),
30|  });
31|  return (await res.json()) as ImageResponse;
32|}
33|
34|// Scene illustration state: the client sends ordinals and ids only,
35|// never text. The scene id comes from the route, never from a DOM scan.
36|// The image survives sub-page moves and clears on scene change because
37|// the scene view remounts per scene id.
38|export function usePictureScene({
39|  bookId,
40|  textVersion,
41|  sceneId,
42|}: {
43|  bookId: string;
44|  textVersion: string;
45|  sceneId: string;
46|}) {
47|  const [card, setCard] = useState<PictureCard>({ phase: "idle" });
48|  const [popover, setPopover] = useState<{ top: number; left: number } | null>(null);
49|  const viewRef = useRef<HTMLDivElement | null>(null);
50|  const popRef = useRef<HTMLButtonElement | null>(null);
51|  const pollLeft = useRef(0);
52|
53|  const hidePopover = useCallback(() => setPopover(null), []);
54|
55|  const request = useCallback(async (body: unknown) => {
56|    // One snapshot per request: every post of this request, including
57|    // pending re-polls, carries the same style, so one chapter uses one style.
58|    const style = loadImageStyle();
59|    const payload =
60|      style === null || typeof body !== "object" || body === null ? body : { ...body, style };
61|    setPopover(null);
62|    setCard({ phase: "loading" });
63|    pollLeft.current = POLL_MAX;
64|    for (;;) {
65|      let res: ImageResponse;
66|      try {
67|        res = await postImage(payload);
68|      } catch {
69|        setCard({ phase: "error", message: MSG_FAILED });
70|        return;
71|      }
72|      if (res.status === "ready") {
73|        setCard({ phase: "ready", url: res.url, caption: res.caption, cached: res.cached });
74|        return;
75|      }
76|      if (res.status === "error") {
77|        setCard({ phase: "error", message: res.message });
78|        return;
79|      }
80|      pollLeft.current -= 1;
81|      if (pollLeft.current <= 0) {
82|        setCard({ phase: "error", message: MSG_RETRY });
83|        return;
84|      }
85|      await new Promise((done) => setTimeout(done, POLL_MS));
86|    }
87|  }, []);
88|
89|  const illustrateScene = useCallback(() => {
90|    if (!sceneId || card.phase === "loading") return;
91|    void request({ kind: "scene", bookId, textVersion, sceneId });
92|  }, [bookId, textVersion, sceneId, request, card.phase]);
93|
94|  const illustratePassage = useCallback(() => {
95|    const view = viewRef.current;
96|    const sel = window.getSelection();
97|    if (!view || !sel || !sel.rangeCount) return;
98|    const entries: ParaEntry[] = [...view.querySelectorAll("p[id][data-n]")].map((el) => ({
99|      id: el.id,
100|      n: Number(el.getAttribute("data-n")),
101|    }));
102|    const n = pickStartN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
103|    if (n === null || !Number.isInteger(n) || card.phase === "loading") return;
104|    void request({ kind: "passage", bookId, textVersion, n });
105|  }, [bookId, textVersion, request, card.phase]);
106|
107|  const dismissCard = useCallback(() => setCard({ phase: "idle" }), []);
108|
109|  // "Picture this" popover: on mouseup, after a frame, show it above the
110|  // selection when the trimmed text is at least 3 chars inside the scene.
111|  // Hidden while an image loads.
112|  useEffect(() => {
113|    const view = viewRef.current;
114|    if (!view) return;
115|    let frame = 0;
116|    const onMouseUp = () => {
117|      cancelAnimationFrame(frame);
118|      frame = requestAnimationFrame(() => {
119|        const sel = window.getSelection();
120|        const text = sel?.toString().trim() ?? "";
121|        if (!sel || sel.isCollapsed || text.length < 3 || !sel.rangeCount) {
122|          setPopover(null);
123|          return;
124|        }
125|        if (!view.contains(sel.anchorNode) || !view.contains(sel.focusNode)) {
126|          setPopover(null);
127|          return;
128|        }
129|        const box = sel.getRangeAt(0).getBoundingClientRect();
130|        const host = view.getBoundingClientRect();
131|        setPopover({
132|          top: box.top - host.top - 8,
133|          left: box.left - host.left + box.width / 2,
134|        });
135|      });
136|    };
137|    view.addEventListener("mouseup", onMouseUp);
138|    return () => {
139|      cancelAnimationFrame(frame);
140|      view.removeEventListener("mouseup", onMouseUp);
141|    };
142|  }, [sceneId]);
143|
144|  // Any mousedown outside the popover dismisses it, as does Escape.
145|  useEffect(() => {
146|    if (!popover) return;
147|    const onDown = (event: MouseEvent) => {
148|      if (!popRef.current?.contains(event.target as Node | null)) setPopover(null);
149|    };
150|    const onKey = (event: KeyboardEvent) => {
151|      if (event.key === "Escape") setPopover(null);
152|    };
153|    document.addEventListener("mousedown", onDown);
154|    document.addEventListener("keydown", onKey);
155|    return () => {
156|      document.removeEventListener("mousedown", onDown);
157|      document.removeEventListener("keydown", onKey);
158|    };
159|  }, [popover]);
160|
161|  const loading = card.phase === "loading";
162|  return {
163|    card,
164|    popover: loading ? null : popover,
165|    viewRef,
166|    popRef,
167|    illustrateScene,
168|    illustratePassage,
169|    hidePopover,
170|    dismissCard,
171|  };
172|}
173|
174|// Inline result slot under the scene heading: image, loading, and error
175|// share one place, with a dismiss button on the finished card.
176|export function PictureSlot({
177|  card,
178|  onDismiss,
179|}: {
180|  card: PictureCard;
181|  onDismiss: () => void;
182|}) {
183|  if (card.phase === "idle") return null;
184|  return (
185|    <div className="picture-slot">
186|      {card.phase === "ready" ? (
187|        <figure className="picture-card">
188|          <img src={card.url} alt={card.caption} className="picture-img" />
189|          <figcaption>
190|            {card.caption} <span className="picture-flag">{card.cached ? "Saved" : "New"}</span>
191|            <button
192|              type="button"
193|              className="picture-dismiss"
194|              onClick={onDismiss}
195|              aria-label="Dismiss image"
196|              title="Dismiss image"
197|            >
198|              ×
199|            </button>
200|          </figcaption>
201|        </figure>
202|      ) : card.phase === "loading" ? (
203|        <div className="picture-loading" role="status" aria-label="Illustrating">
204|          Illustrating…
205|        </div>
206|      ) : (
207|        <p className="picture-error" role="alert">
208|          {card.message}
209|        </p>
210|      )}
211|    </div>
212|  );
